import { Auth } from "../route/auth.js";
import { AuthOptions } from "../route/auth-options.js";
import { MediaRoute } from "../route/media.js";
import { ProviderID } from "../schema/index.js";
import { AssemblyAITranscription } from "../protocols/assemblyai-transcription.js";
export const id = ProviderID.make("assemblyai");
// The key is the whole `authorization` value, without a scheme.
const auth = (options) => AuthOptions.apiKey(options, "ASSEMBLYAI_API_KEY", Auth.header("authorization"));
export const configure = (input = {}) => {
    const media = MediaRoute.deployment(input, auth(input));
    const transcription = (modelID) => AssemblyAITranscription.model({ ...media, id: modelID });
    return {
        id,
        transcription,
        configure,
    };
};
export const provider = configure();
export const transcription = provider.transcription;
